        char out[200]; int len = 0;
        for (int k = 0; k < n && a && !IsBadReadPtr((char *)a + o[k], 4); k++) len += snprintf(out + len, sizeof out - len, " +%x %.3f", o[k], *(float *)((char *)a + o[k]));
        out[len] = 0;
        bot_log("vpeek: %08x%s", a, out);
