        float rx = atkT[0] - m[12], ry = atkT[1] - alt, rz = atkT[2] - m[14], rh = sqrtf(rx * rx + rz * rz) + 1e-3f, r3 = sqrtf(rh * rh + ry * ry);
        float wantH = atan2f(rx, rz) * 57.29578f, eh = wantH - hdg;
        while (eh > 180.0f) eh -= 360.0f;
        while (eh < -180.0f) eh += 360.0f;
