        float R[3] = {atkA[0] - ox, atkA[1] - oy, atkA[2] - oz}, V[3] = {g_heliVel[i][0], g_heliVs[i], g_heliVel[i][1]}, D[3];
        float gsp = heli_gun_speed(i), tf = sqrtf(R[0] * R[0] + R[1] * R[1] + R[2] * R[2]) / gsp;
